from fastapi.testclient import TestClient
from pydantic import BaseModel, Field

app = FastAPI()

class MyHeaders(BaseModel):
    my_header: str = Field(..., alias="my_header") # This is not how Header(convert_underscores=False) works for models

@app.get("/headers")
async def read_headers(headers: MyHeaders = Header(convert_underscores=False)):
    return {"my_header": headers.my_header}

client = TestClient(app)

def test_underscore_header():
    # convert_underscores=False. Should accept my_header, NOT my-header.
    response = client.get("/headers", headers={"my_header": "underscore_value"})
    print(f"Response with my_header: {response.json()}")

    response = client.get("/headers", headers={"my-header": "hyphen_value"})
    print(f"Response with my-header: {response.json()}")

if __name__ == "__main__":
    test_underscore_header()
